with e as (select $1::jsonb j), cfg as (select coalesce((select valor from serena_config where chave = 'wpp_pausa_humano_min'), '120')::int as minutos), c as (select s.id from serena_contatos s, e where s.telefone = '+' || serena_tel_canon(e.j->>'telefone') order by s.atualizado_em desc limit 1), eco as (select 1 from serena_mensagens m, c, e where m.contato_id = c.id and m.papel in ('serena', 'humano') and m.criado_em > now() - interval '3 minutes' and m.texto = e.j->>'texto'), liga as (delete from serena_wpp_pausas p using e where p.telefone = serena_tel_canon(e.j->>'telefone') and e.j->>'comando' = 'on' returning 1), pausa as (insert into serena_wpp_pausas (telefone, ate, motivo) select serena_tel_canon(e.j->>'telefone'), case when e.j->>'comando' = 'off' then now() + interval '30 days' else now() + make_interval(mins => cfg.minutos) end, case when e.j->>'comando' = 'off' then 'comando_off' else 'humano_celular' end from e, cfg where nullif(e.j->>'telefone', '') is not null and coalesce(e.j->>'comando', '') <> 'on' and not exists (select 1 from eco) on conflict (telefone) do update set ate = excluded.ate, motivo = excluded.motivo, atualizado_em = now() returning ate), msg as (insert into serena_mensagens (contato_id, papel, texto, canal, autor, entregue, criado_em) select c.id, 'humano', e.j->>'texto', 'whatsapp', 'celular', true, now() from e, c where coalesce(e.j->>'comando', '') = '' and not exists (select 1 from eco) returning id) select (select ate from pausa) as pausada_ate, (select id from msg)::text as msg_id, (select count(*) from liga)::int as reativada
